---RefreshUI

---@param oneMatchChartData table 一场对阵数据 leftPlayerId leftInfo rightPlayerId rightInfo positionWheel matchResultIndex inBattle
---@param winPlayerId2win table<string, boolean> {["playerId"] = isWin}
---@param isFinal boolean 是否是最终赛
---@param isRealLastWheel boolean 是否是能比赛的最后一轮
function PVPArenaMatchChartAgainstStateNode:RefreshUI(oneMatchChartData, winPlayerId2win, isFinal, isRealLastWheel, lineNodeIdx)
    local isShowLeftEffect  = false
    local isShowRightEffect = false
    local isReplay          = false
    local isInBattle        = false
    local groupIndex        = -1
    local isShowEffect1      = false
    local isShowEffect2      = false
    local lineBattleAniName
    if oneMatchChartData ~= nil then
        local leftScore  = checkNumber(oneMatchChartData.leftScore)
        local rightScore = checkNumber(oneMatchChartData.rightScore)
        isReplay               = leftScore > 0 or rightScore > 0
        isInBattle             = oneMatchChartData.inBattle
        if isReplay then
            self.oneMatchChartData = oneMatchChartData
            local leftPlayerId  = oneMatchChartData.leftPlayerId
            local rightPlayerId = oneMatchChartData.rightPlayerId
            local isLeftWin        = leftScore > rightScore
            local isRightWin       = rightScore > leftScore
            groupIndex = checkTable(self.playerId2Group[tostring(leftPlayerId)]).groupIndex

            local leftNowResultIsWin  = winPlayerId2win[tostring(leftPlayerId)] == true
            local rightNowResultIsWin = winPlayerId2win[tostring(rightPlayerId)] == true

            isShowLeftEffect  = isLeftWin and leftNowResultIsWin
            isShowRightEffect = isRightWin and rightNowResultIsWin

            if isFinal then
                self:RefreshFinalLines(isLeftWin, isRightWin, leftNowResultIsWin, rightNowResultIsWin, isRealLastWheel)
            else
                self:RefreshGroupLines(isLeftWin, isRightWin, leftNowResultIsWin, rightNowResultIsWin)
            end

            local LinePointImageName  = isFinal and "pvp_map_img_linepoint_red_02" or "pvp_map_img_linepoint_blue_02"
            self.LinePoint:LoadSprite(string.format(BasePath, LinePointImageName))
        end

        local isShowEffect = isShowLeftEffect or isShowRightEffect
        if isShowEffect then
            local isHideEffect = false
            if isFinal then
                --- 如果是 最后比赛的最后一轮 并且 是争夺34的比赛的话 隐藏比赛
                isHideEffect = isRealLastWheel and lineNodeIdx == 1

                ---左侧ABCD组的EffectNode动画使用Left；
                ---右侧EFGH组的EffectNode动画使用Right；
                self.animateName = groupIndex <= 4 and LeftAniHash or RightAniHash
            else
                self.animateName = DefaultAniHash
            end
            isShowEffect1  = isShowLeftEffect and not isHideEffect
            isShowEffect2 = isShowRightEffect and not isHideEffect
        end

        if isInBattle then
            lineBattleAniName = (isRealLastWheel or not isFinal) and HorizontalAniHash or VerticalAniHash
        end
    end

    self.EffectNode2.enabled = isShowEffect1
    if not isShowEffect1 then
        self.EffectNode1:StopAllRunClip()
    end
    self.EffectNode2.enabled = isShowEffect2
    if not isShowEffect2 then
        self.EffectNode2:StopAllRunClip()
    end

    if not isInBattle then
        self.UI_PVPLineBattle:StopAllRunClip()
    elseif lineBattleAniName then
        self.UI_PVPLineBattle:Play(lineBattleAniName)
    end

    KTool.SetActive(self.EffectNode1.gameObject, isShowEffect1)
    KTool.SetActive(self.EffectNode2.gameObject, isShowEffect2)
    KTool.SetActive(self.ButtonReplay.gameObject, isReplay)
    KTool.SetActive(self.BattleState.gameObject, isInBattle)
    self.UI_PVPLineBattle.enabled = isInBattle

    self.isShowEffect1 = isShowEffect1
    self.isShowEffect2 = isShowEffect2

end

---RefreshGroupLines
---刷新小组赛的线
---@param isLeftWin boolean 左侧胜利
---@param isRightWin boolean 右侧胜利
---@param leftNowResultIsWin number 左侧玩家id比赛结果
---@param rightNowResultIsWin number 右侧玩家id比赛结果
function PVPArenaMatchChartAgainstStateNode:RefreshGroupLines(isLeftWin, isRightWin, leftNowResultIsWin, rightNowResultIsWin)

    ------------------------------------------
    --- 获取图片数据
    local haveWon = isLeftWin or isRightWin


    --- 竖线 二者有一个最新的比赛结果胜利 则是 高亮
    local singleLine = (leftNowResultIsWin or rightNowResultIsWin) and "pvp_map_img_line_blue_light_01" or
            --- 二者有一个当前轮有一个比赛结果胜利 则是 dark
            (haveWon and "pvp_map_img_line_blue_dark_01" or "pvp_map_img_line_blue_01")

    --- 横线 有一个最新的比赛结果胜利 则是 高亮
    local dualLine1 = leftNowResultIsWin and "pvp_map_img_line_blue_light_02" or
            --- 有一个当前轮有一个比赛结果胜利 则是 dark
            (isLeftWin and "pvp_map_img_line_blue_dark_02" or "pvp_map_img_line_blue_02")

    local dualLine2 = rightNowResultIsWin and "pvp_map_img_line_blue_light_02" or
            (isRightWin and "pvp_map_img_line_blue_dark_02" or "pvp_map_img_line_blue_02")

    ------------------------------------------
    --- 填充图片

    self.LineV1:LoadSprite(string.format(BasePath, singleLine))
    self.LineH1:LoadSprite(string.format(BasePath, dualLine1))
    self.LineH2:LoadSprite(string.format(BasePath, dualLine2))
end

---RefreshFinalLines
---刷新最终赛线
---@param isLeftWin boolean 如果是最后一轮 则是左侧胜利 否则是上侧胜利
---@param isRightWin boolean 如果是最后一轮 则是右侧胜利 否则是下侧胜利
---@param leftNowResultIsWin boolean 如果是最后一轮 则是左侧玩家id最新比赛结果 否则是上侧玩家id最新比赛结果
---@param rightNowResultIsWin boolean 如果是最后一轮 则是右侧玩家id最新比赛结果 否则是下侧玩家id最新比赛结果
---@param isRealLastWheel boolean 实际打的最后一轮
function PVPArenaMatchChartAgainstStateNode:RefreshFinalLines(isLeftWin, isRightWin, leftNowResultIsWin, rightNowResultIsWin, isRealLastWheel)
    local haveWon = isLeftWin or isRightWin
    local nowResultIsWin = leftNowResultIsWin or rightNowResultIsWin

    local GetLineName = function(isHorizontal, result1, result2)
        local lineName
        if isHorizontal then
            lineName = result1 and "pvp_map_img_line_redH_light_01" or
                    (result2 and "pvp_map_img_line_redH_dark_01" or "pvp_map_img_line_redH_01")
        else
            lineName = result1 and "pvp_map_img_line_red_light_01" or
                    (result2 and "pvp_map_img_line_red_dark_01" or "pvp_map_img_line_red_01")
        end
        return lineName
    end

    local singleLine = GetLineName(not isRealLastWheel, nowResultIsWin, haveWon)
    local dualLine1 = GetLineName(isRealLastWheel, leftNowResultIsWin, isLeftWin)
    local dualLine2 = GetLineName(isRealLastWheel, rightNowResultIsWin, isRightWin)

    if isRealLastWheel then
        --------------------------------
        --- 显示的 线 LineH1 LineH2 LineV1  3 4名是 LineH1 LineH2

        --- 横线 有一个最新的比赛结果胜利 则是 高亮
        --- 有一个当前轮有一个比赛结果胜利 则是 dark
        self.LineH1:LoadSprite(string.format(BasePath, dualLine1))
        self.LineH2:LoadSprite(string.format(BasePath, dualLine2))

        if KTool.IsActive(self.LineV1.gameObject) then
            --- 竖线 二者有一个最新的比赛结果胜利 则是 高亮
            --- 二者有一个当前轮有一个比赛结果胜利 则是 dark
            self.LineV1:LoadSprite(string.format(BasePath, singleLine))
        end
    else
        --------------------------------
        --- 显示的 线 LineH1 LineV1 LineV2

        --- 横线 二者有一个最新的比赛结果胜利 则是 高亮
        --- 二者有一个当前轮有一个比赛结果胜利 则是 dark
        self.LineH1:LoadSprite(string.format(BasePath, singleLine))

        --- 竖线 有一个最新的比赛结果胜利 则是 高亮
        --- 有一个当前轮有一个比赛结果胜利 则是 dark
        self.LineV2:LoadSprite(string.format(BasePath, dualLine2))
        self.LineV1:LoadSprite(string.format(BasePath, dualLine1))

    end
end

function PVPArenaMatchChartAgainstStateNode:OnEventMatchChartPlayEffect(wheel)
    self:PlayEffectNodeAnimate(wheel)
end

