function PVPArenaMatchChartAgainstStateNode:PlayEffectNodeAnimate(wheel)
    if self.wheel ~= wheel then return end

    if self.isShowEffect1 then
        print("-------------------》》》》》")
        self.EffectNode1:Update(0)
        self.EffectNode1:Play(self.animateName)
    end
    if self.isShowEffect2 then
        print("-------------------》》》》》1")
        self.EffectNode2:Update(0)
        self.EffectNode2:Play(self.animateName)
    end
end

