function PVPArenaMatchChartAgainstStateNode:OnClickReplayAreaActon()
    local oneMatchChartData = self.oneMatchChartData
    if oneMatchChartData == nil then return end

    --- 如果是 1:0 或 0:1 则是由服务端直接出的结果 这种情况是没录像的
    local leftScore  = checkNumber(oneMatchChartData.leftScore)
    local rightScore = checkNumber(oneMatchChartData.rightScore)
    if (leftScore == 1 and rightScore == 0) or (leftScore == 0 and rightScore == 1)  then
        GameUtils.Toast(localize("暂无录像"))
        return
    end

    --- 弹出查看录像界面
    local leftPosition, rightPosition = oneMatchChartData.leftPosition, oneMatchChartData.rightPosition
    ---@type PVPArenaComponent
    local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
    pvpArenaComponent:RequestReply(string.format("%s_%s", leftPosition, rightPosition), function(data)
        local excludeDialogs = {
            {id = Constants.UITypeIds.PVPArenaAgainstDialog}
        }
        PVPArenaUtils.ShowReplyDialog(self.oneMatchChartData, data, excludeDialogs)
    end)
end


